import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { BookStore } from './store.js';

const directory = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(directory, '..');
const publicDirectory = path.join(root, 'public');

const escapeHtml = (value = '') => String(value)
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;')
  .replaceAll("'", '&#039;');

const layout = ({ title, content, home = false }) => `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="theme-color" content="#f3eee4">
    <title>${escapeHtml(title)} · Leafmark</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=DM+Serif+Display:ital@0;1&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="/styles.css">
    <script src="/app.js" defer></script>
  </head>
  <body>
    <header class="site-header">
      <a class="brand" href="/" aria-label="Leafmark home">
        <svg viewBox="0 0 32 32" aria-hidden="true"><path d="M25.5 4.5C15 5 8.8 9.6 7.6 18.2c-.5 3.5.8 6.5 3.1 8.3 1.3-5.6 4.9-10.2 10.7-13.7-4.5 4-7.1 8.8-7.7 14.7 9.4.2 14.4-8.5 11.8-23Z"/><path d="M6 27.5c2.7-6.8 7.4-11.8 14.1-15"/></svg>
        <span>Leafmark</span>
      </a>
      ${home ? '<button class="button button-dark compact" type="button" data-open-dialog><span aria-hidden="true">＋</span> Add a book</button>' : '<a class="back-link" href="/"><span aria-hidden="true">←</span> Back to shelf</a>'}
    </header>
    <main>${content}</main>
    <footer><span>Leafmark</span><span>Made for quiet reading.</span></footer>
    ${home ? addDialog() : ''}
  </body>
</html>`;

const addDialog = (errors = {}, values = {}) => `
<dialog class="book-dialog" data-book-dialog ${Object.keys(errors).length ? 'open' : ''}>
  <div class="dialog-heading">
    <div><p class="eyebrow">A new beginning</p><h2>Add a book</h2></div>
    <button class="icon-button" type="button" data-close-dialog aria-label="Close">×</button>
  </div>
  <form action="/books" method="post">
    <label>Title <span>required</span><input name="title" value="${escapeHtml(values.title)}" required maxlength="160" autocomplete="off"></label>
    ${errors.title ? `<p class="field-error">${escapeHtml(errors.title)}</p>` : ''}
    <label>Author <span>required</span><input name="author" value="${escapeHtml(values.author)}" required maxlength="120" autocomplete="off"></label>
    ${errors.author ? `<p class="field-error">${escapeHtml(errors.author)}</p>` : ''}
    <label>Notes <span>optional</span><textarea name="notes" maxlength="4000" placeholder="A thought, a quote, why you picked it up…">${escapeHtml(values.notes)}</textarea></label>
    <div class="dialog-actions"><button class="button button-plain" type="button" data-close-dialog>Cancel</button><button class="button button-rust" type="submit">Add to reading</button></div>
  </form>
</dialog>`;

const bookCard = (book) => `
<article class="book-card">
  <a class="book-card-main" href="/books/${encodeURIComponent(book.id)}">
    <div class="mini-cover" aria-hidden="true"><span>${escapeHtml(book.title.slice(0, 1).toUpperCase())}</span></div>
    <div class="book-card-copy">
      <h3>${escapeHtml(book.title)}</h3>
      <p class="author">by ${escapeHtml(book.author)}</p>
      ${book.notes ? `<p class="note-preview">${escapeHtml(book.notes)}</p>` : '<p class="note-preview muted">No notes yet.</p>'}
    </div>
    <span class="arrow" aria-hidden="true">↗</span>
  </a>
  ${book.status === 'reading' ? `<form class="finish-form" action="/books/${encodeURIComponent(book.id)}/finish" method="post"><button class="text-action" type="submit"><span aria-hidden="true">✓</span> Mark finished</button></form>` : `<p class="finished-date">Finished ${formatDate(book.finishedAt)}</p>`}
</article>`;

const emptyState = (kind) => `<div class="empty-state">
  <span aria-hidden="true">${kind === 'reading' ? '☕' : '✓'}</span>
  <p>${kind === 'reading' ? 'Nothing on the go yet.' : 'Your finished books will gather here.'}</p>
  ${kind === 'reading' ? '<button type="button" data-open-dialog>Choose your next read</button>' : ''}
</div>`;

const formatDate = (date) => new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(date));

const homePage = (books, formState) => {
  const reading = books.filter((book) => book.status === 'reading');
  const finished = books.filter((book) => book.status === 'finished');
  return layout({
    title: 'My books',
    home: true,
    content: `<section class="hero">
      <p class="eyebrow">Your reading life</p>
      <h1>Books worth<br><em>remembering.</em></h1>
      <p class="lede">A quiet place to keep the stories you're in, and the ones that stay with you.</p>
      <div class="shelf-rule" aria-hidden="true"><span></span><i></i></div>
    </section>
    <div class="library">
      <section class="book-section">
        <div class="section-title"><div><p class="eyebrow">On the nightstand</p><h2>Currently reading</h2></div><span class="count">${reading.length}</span></div>
        <div class="book-list">${reading.length ? reading.map(bookCard).join('') : emptyState('reading')}</div>
      </section>
      <section class="book-section finished-section">
        <div class="section-title"><div><p class="eyebrow">The archive</p><h2>Finished</h2></div><span class="count">${finished.length}</span></div>
        <div class="book-list">${finished.length ? finished.map(bookCard).join('') : emptyState('finished')}</div>
      </section>
    </div>
    ${formState ? `<script>window.__reopenBookDialog = true</script>` : ''}`,
  }).replace(addDialog(), addDialog(formState?.errors, formState?.values));
};

const detailPage = (book) => layout({
  title: book.title,
  content: `<article class="detail-page">
    <div class="detail-meta"><span class="status ${book.status}">${book.status === 'reading' ? 'Currently reading' : 'Finished'}</span>${book.finishedAt ? `<span>${formatDate(book.finishedAt)}</span>` : `<span>Added ${formatDate(book.createdAt)}</span>`}</div>
    <h1>${escapeHtml(book.title)}</h1>
    <p class="detail-author">by ${escapeHtml(book.author)}</p>
    <div class="ornament" aria-hidden="true"><span></span><i>✦</i><span></span></div>
    <section class="notes-panel"><p class="eyebrow">Notes & fragments</p><div class="notes-copy">${book.notes ? escapeHtml(book.notes).replaceAll('\n', '<br>') : '<span class="muted">No notes for this book yet.</span>'}</div></section>
    <div class="detail-actions">
      ${book.status === 'reading' ? `<form action="/books/${encodeURIComponent(book.id)}/finish" method="post"><button class="button button-rust" type="submit"><span aria-hidden="true">✓</span> Mark as finished</button></form>` : ''}
      <button class="button button-outline" type="button" data-copy-link><span aria-hidden="true">↗</span> Copy book link</button>
    </div>
  </article>`,
});

const errorPage = (status, title, message) => layout({ title, content: `<section class="error-page"><p class="eyebrow">Error ${status}</p><h1>${escapeHtml(title)}</h1><p>${escapeHtml(message)}</p><a class="button button-dark" href="/">Return to your shelf</a></section>` });

const readBody = async (request) => {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > 64 * 1024) throw new Error('Request is too large');
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
};

const send = (response, status, body, type = 'text/html; charset=utf-8') => {
  response.writeHead(status, { 'content-type': type, 'x-content-type-options': 'nosniff' });
  response.end(body);
};

const redirect = (response, location) => {
  response.writeHead(303, { location });
  response.end();
};

export const createApp = async ({ dataFile = process.env.DATA_FILE || path.join(root, 'data', 'books.json') } = {}) => {
  const store = new BookStore(dataFile);
  await store.initialize();

  return createServer(async (request, response) => {
    try {
      const url = new URL(request.url, `http://${request.headers.host || 'localhost'}`);

      if (request.method === 'GET' && (url.pathname === '/styles.css' || url.pathname === '/app.js')) {
        const file = await readFile(path.join(publicDirectory, url.pathname.slice(1)));
        return send(response, 200, file, url.pathname.endsWith('.css') ? 'text/css; charset=utf-8' : 'text/javascript; charset=utf-8');
      }

      if (request.method === 'GET' && url.pathname === '/') return send(response, 200, homePage(await store.all()));

      if (request.method === 'POST' && url.pathname === '/books') {
        const form = await readBody(request);
        const values = { title: form.get('title') || '', author: form.get('author') || '', notes: form.get('notes') || '' };
        const errors = {};
        if (!values.title.trim()) errors.title = 'Please add a title.';
        if (!values.author.trim()) errors.author = 'Please add an author.';
        if (Object.keys(errors).length) return send(response, 422, homePage(await store.all(), { values, errors }));
        const book = await store.create(values);
        return redirect(response, `/books/${encodeURIComponent(book.id)}`);
      }

      const detailMatch = url.pathname.match(/^\/books\/([^/]+)$/);
      if (request.method === 'GET' && detailMatch) {
        const book = await store.find(decodeURIComponent(detailMatch[1]));
        if (!book) return send(response, 404, errorPage(404, 'Book not found', 'This book may have been moved or the link may be incomplete.'));
        return send(response, 200, detailPage(book));
      }

      const finishMatch = url.pathname.match(/^\/books\/([^/]+)\/finish$/);
      if (request.method === 'POST' && finishMatch) {
        const id = decodeURIComponent(finishMatch[1]);
        const book = await store.finish(id);
        if (!book) return send(response, 404, errorPage(404, 'Book not found', 'We could not find that book on your shelf.'));
        const returnTo = request.headers.referer && new URL(request.headers.referer).pathname === `/books/${id}` ? `/books/${encodeURIComponent(id)}` : '/';
        return redirect(response, returnTo);
      }

      return send(response, 404, errorPage(404, 'Page not found', 'There is nothing written on this page.'));
    } catch (error) {
      console.error(error);
      return send(response, error.message === 'Request is too large' ? 413 : 500, errorPage(500, 'Something went wrong', 'Leafmark could not complete that request. Please try again.'));
    }
  });
};

if (process.env.NODE_ENV !== 'test') {
  const port = Number(process.env.PORT) || 3000;
  const server = await createApp();
  server.listen(port, () => console.log(`Leafmark is ready at http://localhost:${port}`));
}

